  ('zh-CN', 'docs.orgRepositories.usage', $json$"在网站上打开组织，进入“仓库”，连接提供方并添加仓库。在应用中，组织页面会随变化实时列出它们：选择组织文件夹，克隆缺少的仓库，并用“查找克隆”在所有层级中将整个文件夹与网站上的列表进行对比。"$json$::jsonb),
  ('hi', 'org.gitNotConnected', $json$"इसकी रिपॉज़िटरी जोड़ने से पहले git प्रदाता कनेक्ट करें।"$json$::jsonb),
  ('hi', 'org.gitExpired', $json$"इस साइट पर git प्रदाता का सत्र समाप्त हो गया है। इसे फिर से कनेक्ट करें।"$json$::jsonb),
  ('hi', 'org.gitUnavailable', $json$"git प्रदाता ने जवाब नहीं दिया। थोड़ी देर में फिर से कोशिश करें।"$json$::jsonb),
