  ('hi', 'site.org.git.description', $json$"ओनर यहाँ GitHub, GitLab या Bitbucket में साइन इन करता है और संगठन की रिपॉज़िटरी चुनता है। ऐक्सेस टोकन इस साइट पर सिर्फ़ एक घंटे रहता है और कभी सहेजा नहीं जाता।"$json$::jsonb),
