  ('hi', 'whatsNew.item.repositoriesFromSite.detail', $json$"ओनर अब JayV साइट पर GitHub, GitLab या Bitbucket में साइन इन करके संगठन की रिपॉज़िटरी जोड़ता है, और वे ऐप में अपने-आप दिखती हैं। रिपॉज़िटरी URL चिपकाने वाला फ़ील्ड ऐप से हटा दिया गया है।"$json$::jsonb),
  ('hi', 'whatsNew.item.folderCompare.title', $json$"क्लोन खोजें अब पूरा फ़ोल्डर देखता है"$json$::jsonb),
