  ('hi', 'docs.organizations.usage', $json$"JayV साइट के डैशबोर्ड में संगठन बनाएँ, सदस्यों को आमंत्रित करें और उसकी रिपॉज़िटरी जोड़ें। ऐप में Ctrl+2 (Mac पर ⌘2) आपके संगठन और उनकी रिपॉज़िटरी खोलता है।"$json$::jsonb),
  ('hi', 'docs.orgRepositories.title', $json$"संगठन की रिपॉज़िटरी"$json$::jsonb),
  ('hi', 'docs.orgRepositories.summary', $json$"ओनर JayV साइट पर GitHub, GitLab या Bitbucket में साइन इन करके संगठन की रिपॉज़िटरी जोड़ता है। ऐप इन्हें अपने-आप दिखाता है, और हर सदस्य अपनी git ऐक्सेस से इन्हें क्लोन करता है।"$json$::jsonb),
  ('hi', 'docs.orgRepositories.usage', $json$"साइट पर संगठन खोलें, रिपॉज़िटरी में जाएँ, कोई प्रदाता कनेक्ट करें और रिपॉज़िटरी जोड़ें। ऐप में संगठन का पेज बदलाव होते ही इन्हें दिखाता है: संगठन का फ़ोल्डर चुनें, जो नहीं है उसे क्लोन करें और क्लोन खोजें से पूरे फ़ोल्डर की, हर गहराई तक, साइट की सूची से तुलना करें।"$json$::jsonb),
